#!/bin/bash
# PREREG18: rerun, alone and by name, every stand of arm $1 whose FAIL_REASON is a host time limit, up to three attempts;
# attempt k reruns the stands still timed out after attempt k-1. Generated by sed from retry_timeouts_p17_rev2.sh (md5
# 5eb7f136); only the driver name changes. Usage: HOME=<bundle home> bash retry_timeouts_p18.sh <COL>. Writes
# out_retry_a<k>/ only; never touches out/. No coordinates. No em dashes.
set -uo pipefail
COL=$1; cd $HOME; L=$HOME/logs/retry_$COL.log
cid() { printf %s "$1" | cksum | cut -d' ' -f1; }
todo() { for f in out/$COL/*/c*_results.csv; do s=$(basename $(dirname $f))
    grep -a 'reached elapsed time limit' $f | cut -d, -f1 | tr -d '"' | while read st; do id=$(cid "$st")
      last=""; for k in 1 2 3; do g=out_retry_a$k/$COL/$s/c${id}_results.csv; [ -e $g ] && last=$g; done
      if [ -z "$last" ] || grep -aq 'reached elapsed time limit' $last; then echo "$s $st"; fi
    done; done; }
for k in 1 2 3; do
  todo | while read s st; do id=$(cid "$st")
    [ -e out_retry_a$k/$COL/$s/c${id}_results.csv ] && continue
    echo "attempt $k $COL $s $st start $(date -Is)" >> $L
    bash run_retry_p18.sh $COL $s "$st" $k >> $L 2>&1; echo "attempt $k $COL $s $st exit $? $(date -Is)" >> $L
  done
done
echo "RETRY_DONE $COL remaining: $(todo | wc -l)" >> $L
